import { assertSafeSetupCommand } from "./setup-hook-status.js";
/**
 * Generate the source for an OpenCode global plugin.
 *
 * The generated plugin deliberately has no OpenCode package import. OpenCode
 * loads global plugins in its own runtime, while Agent LCM only needs the
 * Node-compatible child-process API to hand events to the capture command.
 */
export function generateOpenCodePluginSource(command) {
    assertSafeSetupCommand(command);
    const commandLiteral = JSON.stringify(command);
    return `// agent-lcm-opencode-plugin: 1
// Generated by Agent LCM. Do not edit.
import { spawn } from "node:child_process";
import fs from "node:fs";

const AGENT_LCM_COMMAND = ${commandLiteral};
const AGENT_LCM_STATE = new URL("./.agent-lcm-opencode-plugin.state", import.meta.url);
const AGENT_LCM_PRIMARY_PLUGIN = "agent-lcm.ts";

function captureEnabled() {
  try {
    if (!import.meta.url.endsWith("/" + AGENT_LCM_PRIMARY_PLUGIN)) return false;
    return fs.readFileSync(AGENT_LCM_STATE, "utf8").split("\\n", 1)[0] === "enabled";
  } catch {
    return false;
  }
}

function capture(hookEvent, payload) {
  if (!captureEnabled()) return;
  let input;
  try {
    input = JSON.stringify(payload);
    const child = spawn("node", [AGENT_LCM_COMMAND, "capture", "--harness", "opencode", hookEvent], {
      shell: false,
      stdio: ["pipe", "ignore", "ignore"],
    });
    child.on("error", () => {});
    child.stdin.on("error", () => {});
    child.stdin.end(input);
  } catch {
    // Capture must never interfere with the OpenCode request lifecycle.
  }
}

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function has(value, key) {
  return isRecord(value) && Object.prototype.hasOwnProperty.call(value, key);
}

function firstString(...values) {
  return values.find((value) => typeof value === "string" && value.length > 0);
}

function sessionId(value) {
  if (!isRecord(value)) return undefined;
  const info = isRecord(value.info) ? value.info : undefined;
  return firstString(value.sessionID, value.sessionId, value.session_id, value.id, info?.id);
}

function withSessionId(value, id) {
  const payload = isRecord(value) ? { ...value } : {};
  if (id && !has(payload, "sessionID")) payload.sessionID = id;
  return payload;
}

function withCwd(payload, cwd) {
  payload.cwd = cwd;
  return payload;
}

function sessionEventPayload(event, cwd) {
  const properties = isRecord(event?.properties) ? event.properties : {};
  const info = isRecord(properties.info) ? properties.info : properties;
  const id = sessionId(properties) ?? sessionId(info);
  return withCwd(withSessionId({ ...properties, event_type: event?.type }, id), cwd);
}

function chatMessagePayload(input, output, cwd) {
  const id = sessionId(input);
  const payload = withSessionId({ ...(isRecord(input) ? input : {}) }, id);
  const parts = Array.isArray(output?.parts) ? output.parts : [];
  const text = parts
    .filter((part) => isRecord(part) && part.type === "text" && typeof part.text === "string")
    .map((part) => part.text)
    .join("");
  payload.prompt = text;
  payload.parts = parts;
  if (isRecord(output) && has(output, "metadata")) payload.metadata = output.metadata;
  return withCwd(payload, cwd);
}

function toolAfterPayload(input, output, cwd) {
  const id = sessionId(input);
  const payload = withSessionId({
    ...(isRecord(input) ? input : {}),
    ...(isRecord(output) ? output : {}),
  }, id);
  if (has(input, "tool")) payload.tool_name = input.tool;
  if (has(input, "callID")) payload.tool_use_id = input.callID;
  if (has(input, "args")) payload.tool_input = input.args;
  if (has(output, "output")) payload.tool_response = output.output;
  return withCwd(payload, cwd);
}

export const AgentLcmPlugin = async ({ directory } = {}) => {
  const cwd = typeof directory === "string" ? directory : process.cwd();
  return {
    event: async ({ event }) => {
      if (event?.type === "session.created") {
        capture("SessionStart", sessionEventPayload(event, cwd));
      } else if (event?.type === "session.idle") {
        capture("Stop", sessionEventPayload(event, cwd));
      }
    },
    "chat.message": async (input, output) => {
      capture("UserPromptSubmit", chatMessagePayload(input, output, cwd));
    },
    "tool.execute.after": async (input, output) => {
      capture("PostToolUse", toolAfterPayload(input, output, cwd));
    },
  };
};
export default AgentLcmPlugin;
`;
}
